public class Singleton {
    private static Singleton instance = null;
    public static Singleton getInstance() {
        synchronized(Singleton.class) {
            if (instance == null) {
                Singleton instance = new Singleton();
                return instance;
            }
        }
        return instance;
    }
}

public class Singleton {
    private static Singleton instance = null;
    public static Singleton getInstance() {
        synchronized(Singleton.class){
            if (instance == null) {
                instance = new Singleton();
            }
        }
        return instance;
    }
}

public final class Foo {
    private static volatile Foo myFoo;
    public static Foo getInstance() {
        Foo instance = myFoo;
        if (instance == null) {
            synchronized (Foo.class) {
                instance = myFoo;
                if (instance == null) {
                    myFoo = instance = new Foo(); // here: double assignment to instance and then field
                }
            }
        }
        return instance;
    }
}

public final class Foo {
    private static volatile Foo myFoo;
    public static Foo getInstance() {
        Foo instance = myFoo;
        if (instance == null) {
            synchronized (Foo.class) {
                instance = myFoo;
                if (instance == null) {
                    instance = myFoo = new Foo(); // here: double assignment to field and then instance
                }
            }
        }
        return instance;
    }
}

public final class ObjectArrayValidatorNoOp implements ObjectArrayValidator<Object, Object> {
    private static final ObjectArrayValidatorNoOp INSTANCE = new ObjectArrayValidatorNoOp();

    public static <T, E> ObjectArrayValidator<T, E> getInstance() {
        @SuppressWarnings("unchecked")
        ObjectArrayValidator<T, E> temp = (ObjectArrayValidator<T, E>) (Object) INSTANCE;
        return temp;
    }
}
interface ObjectArrayValidator<T, E> { }

public class Singleton {
    private static Singleton instance;
    public static Singleton getInstance() {
        Singleton result = instance;
        if (result == null) {
            result = new Singleton();
        }
        return result;
    }
}

public class Singleton {
    private static Singleton instance;
    public static Object getInstance() {
        Object result = instance != null ? instance : (Object) new Singleton();
        return result;
    }
}
